const rows = $input.all().map(i => i.json).filter(j => j && (j.canonical_url || j.id));
if (!rows.length) return [{ json: { count: 0, items: [], note: 'no feed items matched the filters' } }];
const grouped = rows.some(r => Number(r.articles) > 1);
return [{ json: { count: rows.length, grouped_by_story: Boolean($('WF Input').first().json.group_stories), items: rows, note: grouped ? 'articles > 1 means several outlets covered the same story' : undefined } }];
